SELECT set_config('test.uid',u(1)::text,false);
SELECT assert_true((SELECT count(*)=2 FROM fn_agent_roster_report(u(10),'2026-09-07T07:00Z','2026-09-14T07:00Z')),'overseer sees only their clubs and all four agent levels');
SELECT assert_true((SELECT count(*)=2 FROM fn_agent_roster_report(u(10),'2026-09-07T07:00Z','2026-09-14T07:00Z',u(100))),'a cyclic hierarchy terminates without duplicate players');
SELECT assert_true(refuses($$SELECT * FROM fn_agent_roster_report(u(10),'2026-09-07T07:00Z','2026-09-14T07:00Z',u(200))$$,'42501'),'overseer cannot request another union club');
SELECT assert_true((SELECT sum(rake_generated)=15 AND sum(net_result)=20 FROM fn_agent_roster_report(u(10),'2026-09-07T07:00Z','2026-09-14T07:00Z',u(100))),'cash attribution and posted wallet movement stay in the requested club');
SELECT assert_true((SELECT bool_and(agent_commission IS NULL) FROM fn_agent_roster_report(u(10),'2026-09-07T07:00Z','2026-09-14T07:00Z',u(100))),'unattributable commission is unknown instead of repeating a club total on each player');
SELECT assert_true((SELECT bool_and(NOT currently_seated) FROM fn_agent_roster_report(u(10),'2026-09-07T07:00Z','2026-09-14T07:00Z',u(100))),'seated status in another club is not exposed');
CREATE TEMP TABLE statement AS SELECT fn_agent_weekly_statement(u(10),'2026-09-07T07:00Z','2026-09-14T07:00Z',u(100)) AS data;
SELECT assert_true((SELECT (data->>'commission_earned')::numeric=7 AND (data->>'credit_outstanding')::numeric=2 FROM statement),'commission and debt are not combined across clubs');
SELECT assert_true((SELECT (data->>'rakeback_passed_to_players')::numeric=1 FROM statement),'only posted rakeback funded by this agent is reported as paid');
SELECT assert_true((SELECT data->>'net_settlement_position' IS NULL AND data->>'settlement_verified'='false' FROM statement),'unreconciled earnings cannot produce a purported invoice balance');
SELECT assert_true(refuses($$SELECT * FROM fn_union_weekly_agent_statements(u(201),'2026-09-07T07:00Z')$$,'42501'),'union statements enforce the requested union');
SELECT assert_true((SELECT (s.statement->>'commission_earned')::numeric=7 FROM fn_union_weekly_agent_statements(u(101),'2026-09-07T07:00Z')s WHERE agent_user_id=u(10)),'union statement rows pass their exact club to the shared statement reader');
SELECT assert_true(refuses($$SELECT fn_agent_weekly_statement(u(10),'infinity','infinity',u(100))$$,'22023'),'invalid statement ranges are refused');
SELECT set_config('test.uid',u(10)::text,false);
SELECT assert_true((SELECT count(*)=3 AND sum(rake_generated)=114 FROM fn_agent_roster_report(NULL,'2026-09-07T07:00Z','2026-09-14T07:00Z')),'agent may view own club accounts without duplicating a multi-club player');
SELECT assert_true((SELECT count(*)=1 AND sum(chip_balance)=900 FROM fn_agent_roster_report(NULL,'2026-09-07T07:00Z','2026-09-14T07:00Z',u(200))),'malformed cross-club parent edge does not pull another downline into the account');
SELECT set_config('test.uid',u(30)::text,false);
SELECT assert_true(refuses($$SELECT fn_agent_weekly_statement(u(10),'2026-09-07T07:00Z','2026-09-14T07:00Z')$$,'42501'),'unrelated account cannot view another agent statement');
SELECT set_config('test.uid','',false);
SET ROLE anon;
SELECT assert_true(NOT has_function_privilege(current_user,'fn_agent_weekly_statement(uuid,timestamptz,timestamptz,uuid)','EXECUTE'),'anonymous users cannot call the statement reader');
RESET ROLE;
